using System.Collections.Generic;
using UnityEngine;

namespace SpaceBetweenUs
{
    /// <summary>
    /// All the game's sound in one place. Finds the gameplay objects at Start and listens to their events,
    /// so nothing else has to know about audio:
    ///   ambience per role (cross-fades on the switch), switch whoosh, asteroid hits / taps / violent break,
    ///   island ruined / alive, attract hum, grab, rock placed, ice pouring, water filled, crystal planted,
    ///   life growing, the reveal chord.
    /// Clips are placeholders generated by Space Between Us > Audio (Assets/_Project/Audio). Replace a .wav with a
    /// real sound of the same name and it is used automatically.
    /// </summary>
    public class SoundDirector : MonoBehaviour
    {
        [Header("Ambience (loops)")]
        public AudioClip ambBuilder;
        public AudioClip ambDestroyer;
        [Range(0f, 1f)] public float ambVolume = 0.35f;

        [Header("Destroyer")]
        public AudioClip punch;
        public AudioClip tap;
        public AudioClip violent;
        public AudioClip islandRuin;

        [Header("Builder")]
        public AudioClip attractLoop;
        public AudioClip grab;
        public AudioClip placeRock;
        public AudioClip pourLoop;
        public AudioClip waterFill;
        public AudioClip crystal;
        public AudioClip grow;
        public AudioClip islandAlive;

        [Header("Flow")]
        public AudioClip switchWhoosh;
        public AudioClip reveal;

        [Range(0f, 1f)] public float sfxVolume = 0.9f;

        static SoundDirector _instance;
        readonly List<AudioSource> _pool = new();
        AudioSource _ambA, _ambB, _pour;
        readonly Dictionary<FragmentAttractor, AudioSource> _attract = new();
        readonly Dictionary<FragmentGrabber, MaterialFragment> _held = new();

        GameFlowManager _flow;
        PerspectiveSwitcher _switcher;
        bool _wasSwitching, _revealed;
        float _pourUntil;
        Vector3 _pourPos;

        void Awake()
        {
            _instance = this;
            _ambA = MakeSource("Amb_Builder", ambBuilder, true, 0f);
            _ambB = MakeSource("Amb_Destroyer", ambDestroyer, true, 0f);
            _pour = MakeSource("Pour", pourLoop, true, 0.8f);
            for (int i = 0; i < 12; i++) _pool.Add(MakeSource($"Sfx_{i}", null, false, 0.85f));
        }

        AudioSource MakeSource(string name, AudioClip clip, bool loop, float spatial)
        {
            var go = new GameObject(name);
            go.transform.SetParent(transform, false);
            var a = go.AddComponent<AudioSource>();
            a.clip = clip;
            a.loop = loop;
            a.playOnAwake = false;
            a.spatialBlend = spatial;
            a.rolloffMode = AudioRolloffMode.Logarithmic;
            a.dopplerLevel = 0f;
            a.volume = 0f;
            if (loop && clip) a.Play();
            return a;
        }

        void Start()
        {
            _flow = FindAnyObjectByType<GameFlowManager>();
            _switcher = FindAnyObjectByType<PerspectiveSwitcher>();
            if (_flow) _flow.onReveal.AddListener(OnReveal);

            const FindObjectsInactive all = FindObjectsInactive.Include;
            foreach (var a in FindObjectsByType<Asteroid>(all, FindObjectsSortMode.None))
            {
                var ast = a;
                ast.onLayerOpened.AddListener(_ => Play(punch, ast.transform.position, 1f));
                ast.onTap.AddListener(_ => Play(tap, ast.transform.position, 0.9f));
                ast.onViolentBreak.AddListener(() => Play(violent, ast.transform.position, 1f));
                ast.onOpened.AddListener(() => { if (ast.carefulMode && ast.OpenedGently) Play(crystal, ast.transform.position, 0.8f); });
            }
            foreach (var i in FindObjectsByType<Island>(all, FindObjectsSortMode.None))
            {
                var island = i;
                if (island.onLost != null) island.onLost.AddListener(() => Play(islandRuin, island.transform.position, 1f));
                if (island.onAlive != null) island.onAlive.AddListener(() => Play(islandAlive, island.transform.position, 0.8f));
            }
            foreach (var s in FindObjectsByType<IslandSlot>(all, FindObjectsSortMode.None))
            {
                var slot = s;
                slot.onFilled.AddListener(() =>
                {
                    var clip = slot.accepts == MaterialType.Rock ? placeRock : slot.accepts == MaterialType.Ice ? waterFill : crystal;
                    Play(clip, slot.transform.position, 0.9f);
                });
                if (slot.mode == IslandSlot.Mode.Pour)
                    slot.onProgress.AddListener(p => { if (p > 0f && p < 1f) { _pourUntil = Time.time + 0.2f; _pourPos = slot.transform.position; } });
            }
            foreach (var g in FindObjectsByType<LifeGrowth>(all, FindObjectsSortMode.None))
            {
                var life = g;
                life.onStage.AddListener(_ => Play(grow, life.transform.position, 0.6f));
            }
            foreach (var a in FindObjectsByType<FragmentAttractor>(all, FindObjectsSortMode.None))
                _attract[a] = MakeSource("Attract_" + a.name, attractLoop, true, 0.8f);
            foreach (var g in FindObjectsByType<FragmentGrabber>(all, FindObjectsSortMode.None))
                _held[g] = null;
        }

        void Update()
        {
            float dt = Time.deltaTime;
            // ambience follows the role; quieter during the reveal
            bool destroyer = _switcher && _switcher.Current == Role.Destroyer;
            float amb = _revealed ? ambVolume * 0.4f : ambVolume;
            _ambA.volume = Mathf.MoveTowards(_ambA.volume, destroyer ? 0f : amb, dt * 0.5f);
            _ambB.volume = Mathf.MoveTowards(_ambB.volume, destroyer ? amb : 0f, dt * 0.5f);

            if (_switcher)
            {
                if (_switcher.IsSwitching && !_wasSwitching) Play(switchWhoosh, Vector3.zero, 0.8f, spatial: false);
                _wasSwitching = _switcher.IsSwitching;
            }

            float scale = ListenerScale();
            foreach (var kv in _attract)
            {
                var src = kv.Value;
                bool on = kv.Key && kv.Key.isActiveAndEnabled && kv.Key.Pulling;
                if (kv.Key) src.transform.position = kv.Key.transform.position;
                Fit(src, scale);
                src.volume = Mathf.MoveTowards(src.volume, on ? 0.5f * sfxVolume : 0f, dt * 3f);
            }

            var keys = new List<FragmentGrabber>(_held.Keys);
            foreach (var g in keys)
            {
                var now = g ? g.Held : null;
                if (now && now != _held[g]) Play(grab, g.transform.position, 0.7f);
                _held[g] = now;
            }

            bool pouring = Time.time < _pourUntil;
            _pour.transform.position = _pourPos;
            Fit(_pour, scale);
            _pour.volume = Mathf.MoveTowards(_pour.volume, pouring ? 0.6f * sfxVolume : 0f, dt * 2.5f);
        }

        void OnReveal()
        {
            _revealed = true;
            Play(reveal, Vector3.zero, 0.8f, spatial: false);
        }

        /// <summary>One-shot sound at a world position (or 2D when spatial is false).</summary>
        public static void PlayAt(AudioClip clip, Vector3 pos, float volume, bool spatial = true)
        {
            if (_instance) _instance.Play(clip, pos, volume, spatial);
        }

        void Play(AudioClip clip, Vector3 pos, float volume, bool spatial = true)
        {
            if (!clip) return;
            AudioSource src = null;
            foreach (var s in _pool) if (!s.isPlaying) { src = s; break; }
            if (!src) src = _pool[0];
            src.transform.position = pos;
            src.spatialBlend = spatial ? 0.85f : 0f;
            Fit(src, ListenerScale());
            src.clip = clip;
            src.volume = volume * sfxVolume;
            src.pitch = Random.Range(0.95f, 1.05f);
            src.Play();
        }

        // the Destroyer rig is 20x bigger: scale the audible distances with it
        static void Fit(AudioSource s, float scale)
        {
            s.minDistance = 1.5f * scale;
            s.maxDistance = 80f * scale;
        }

        static float ListenerScale()
        {
            var cam = Camera.main;
            return cam ? Mathf.Max(0.01f, cam.transform.lossyScale.x) : 1f;
        }
    }
}
